-- =============================================================================
-- SEED DATA: 100 CHỦ TRỌ & 1000 PHÒNG TRỌ TOÀN DIỆN CHO HỆ THỐNG ROOMI
-- Tạo tự động: Hỗ trợ kiểm thử tải lớn, bản đồ, lọc phòng, tìm kiếm thông minh
-- Định dạng: PostgreSQL 14+ / H2 Compatible
-- =============================================================================

BEGIN;

-- -----------------------------------------------------------------------------
-- 1. TẠO 100 TÀI KHOẢN CHỦ TRỌ (ROLE_LANDLORD: id 101 -> 200)
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO UPDATE SET updated_at = CURRENT_TIMESTAMP;

-- -----------------------------------------------------------------------------
-- 2. TẠO TÒA NHÀ CHO CÁC CHỦ TRỌ (BUILDINGS: id 101 -> 250)
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO UPDATE SET updated_at = CURRENT_TIMESTAMP;

-- -----------------------------------------------------------------------------
-- 3. TẠO DỊCH VỤ TIỆN ÍCH CHO 100 CHỦ TRỌ (SERVICES: 4 dịch vụ / chủ)
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO UPDATE SET updated_at = CURRENT_TIMESTAMP;

-- -----------------------------------------------------------------------------
-- 4. TẠO ĐÚNG 1000 PHÒNG TRỌ (ROOMS: id 101 -> 1100)
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO UPDATE SET updated_at = CURRENT_TIMESTAMP;

-- -----------------------------------------------------------------------------
-- 5. TẠO ẢNH CHO 1000 PHÒNG TRỌ (ROOM_IMAGES: 2000 ảnh)
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- -----------------------------------------------------------------------------
-- 6. LIÊN KẾT DỊCH VỤ CHO 1000 PHÒNG TRỌ (ROOM_SERVICES: 4000 liên kết)
-- -----------------------------------------------------------------------------
ON CONFLICT (room_id, service_id) DO NOTHING;

-- -----------------------------------------------------------------------------
-- 7. ĐỒNG BỘ LẠI POSTGRESQL SEQUENCES
-- -----------------------------------------------------------------------------
SELECT setval('users_id_seq', (SELECT COALESCE(MAX(id), 1) FROM users));
SELECT setval('buildings_id_seq', (SELECT COALESCE(MAX(id), 1) FROM buildings));
SELECT setval('services_id_seq', (SELECT COALESCE(MAX(id), 1) FROM services));
SELECT setval('rooms_id_seq', (SELECT COALESCE(MAX(id), 1) FROM rooms));
SELECT setval('room_images_id_seq', (SELECT COALESCE(MAX(id), 1) FROM room_images));

COMMIT;
